import React, { useRef, useState } from 'react';
import {
    View,
    Text,
    TouchableOpacity,
    ActivityIndicator,
    Animated,
    Button,
    Dimensions
} from 'react-native';

import { ParamListBase, useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';

import { Alert } from '../../components/Pop-Ups/Alert';

import { useContexState } from '../../hooks/context';
import { useLoadPage } from '../../hooks/loadPage';
import { styles } from './styles';

import api from '../../services/api';

type YourNavigatorProps = NativeStackNavigationProp<ParamListBase, keyof ParamListBase>

interface CardsProps {
    position: number;
    listItemProps: {
        data: { firstCard: number, id: string };
        list?: {
            [key: string]: [{
                id: number;
                name: string;
                phone: string;
                price: number;

                analyzed: number;
            }]
        };
    };
};


interface response {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
        analyzed: number;
    }[]
};

//const randomText = Math.random().toString(36).substr(2, 5);

export function Cards() {
    const {
        isMountedApi,
        shoppingCartItem,
        alertMessage,
        listData,
    } = useContexState();

    const {
        setKeyboardActive,
        setSelectedNumber,
        setAlertActive,
        setPaymentMenuActive,
        setAlertMessage
    } = useContexState();


    const [checkBuyLoad, setCheckBuyLoad] = useState(false)
    const [active, setActive] = useState(false);


    const fadeAnim = useRef(new Animated.Value(0.9)).current;


    const tempShoppingCartItem = [...shoppingCartItem];

    const navigation = useNavigation<YourNavigatorProps>();

    //const { AlertButton } = Alert({ position });
    const { LoadPage } = useLoadPage();









    function fade(value2: number) {

        setActive(true);
        Animated.timing(fadeAnim, {
            toValue: value2,
            duration: 1000,
        } as Animated.TimingAnimationConfig).start(() => {
            if (value2 === 0) {
                setActive(false)
                console.log('sdsdsd')
            };
        });
    };

    function AlertActive(message = '',) {
        setAlertMessage(message);
        fade(1);
        console.log('1313asd')
    }









    // onPress={() => isMountedApi ? checkBuy() : null}





    function ButtonCard({ listItemProps, position }: CardsProps) {
        const cardNumber = listItemProps.data.firstCard + position;
        const index = tempShoppingCartItem.indexOf(cardNumber);




        function AlertMessageSelect() {
            if (shoppingCartItem[index]) {
                return 'O número já está no carrinho!';
            };

            if (listItemProps.list?.[cardNumber][0].analyzed === 0) {
                return 'O número já foi comprado!';
            } else {
                return 'O número está em análise!';
            };
        };














        function colorSelect() {
            if (shoppingCartItem[index]) {
                return { backgroundColor: '#7B68EE' };
            };

            if (listItemProps.list?.[String(cardNumber)]) {
                return {
                    backgroundColor: listItemProps.list?.
                    [cardNumber][0].analyzed !== 0 ? '#26A744' : '#17A2B7'
                };
            } else {
                return {
                    backgroundColor: '#fff',
                    color: '#121212'
                };
            };
        };




        function checkBuy() {
            setCheckBuyLoad(true);
            api.get("getCards", {
                params: {
                    firstNumber: cardNumber,
                    lastNumber: cardNumber,
                }
            }
            ).then((responce: response) => {
                setCheckBuyLoad(false)
                if (!listItemProps.list?.[String(cardNumber)] && responce.data.length === 0) {
                    setPaymentMenuActive(true);
                    setSelectedNumber(cardNumber);
                } else if (listItemProps.list?.[String(cardNumber)] && responce.data.length !== 0) {
                    AlertActive(AlertMessageSelect());
                }

                if (listItemProps.list?.[String(cardNumber)] && responce.data.length === 0) {
                    LoadPage(Number(listData[0]?.firstCard));
                } else if (!listItemProps.list?.[String(cardNumber)] && responce.data.length !== 0) {
                    LoadPage(Number(listData[0]?.firstCard));
                }
            });
        };







        return cardNumber <= 9999 && cardNumber >= 0 ? (
            <TouchableOpacity
                onPress={() => isMountedApi ? checkBuy() : null}
                style={{ alignItems: 'center', justifyContent: 'center' }}>



                <Text
                    style={[styles.listText, colorSelect()]}>
                    {(`0000${cardNumber}`).slice(-4)}
                </Text>


                {!isMountedApi || checkBuyLoad ?
                    <ActivityIndicator
                        style={{ position: 'absolute' }}
                        size={20}
                        color='#121212'
                    /> : null}


            </TouchableOpacity>
        ) : <View />
    }



    function AlertTSX() {
        return <>
            <Button onPress={() => { AlertActive('adasdasd') }} title='Button' />
            {active ? <>
                <TouchableOpacity
                    onPress={() => { fade(0) }}
                    style={{
                        position: 'absolute',
                        alignItems: 'center',
                        justifyContent: 'center',
                        minWidth: Dimensions.get('window').width,
                        minHeight: Dimensions.get('window').height
                    }} />

                <Animated.View style={[styles.container, { opacity: fadeAnim }]} >
                    <Text style={styles.listText}>{alertMessage}</Text>
                </Animated.View>
            </> : null}
        </>
    }


    return {AlertTSX, ButtonCard }
};





















